import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";

const VERSION = "r39-rollback-to-r37";
const PLAYER_FILE = "src/features/music/MusicMiniPlayer.tsx";
const PLAYER_IMPORT = 'import { MusicTodayAi } from "./premium/MusicTodayAi";';
const PLAYER_RENDER_MARKER = "MVP_MUSIC_TODAY_AI_R39";
const R37_HASHES = {
  "src/features/music/MusicPage.tsx": "ecb225826547ba317722f2f09c649570a71c361512dcdbb9627a7a2526c5fcbd",
  "src/features/music/MusicAuditionPanel.tsx": "efe948b1a08fdf95f376ca4251800de4231e9473e59a1f05a6365e63d476e12f",
  "src/features/music/MusicIntelligencePanel.tsx": "33854db112d247b5dc96b542e91b2b545089225b0ba71beeb0c687a766a39e3a",
  "src/features/music/premium/MusicUiPrimitives.tsx": "61a699db718a05b4b877fb100fe8e6fad38304a83247eaa5150dc39f35393426",
  "src/features/music/premium/MusicPremiumSelect.tsx": "37ad95aa7f51365520adcc9710f5d31ae4fe9b85f9879e8e2058677237d6e4c6",
  "src/features/music/premium/MusicUiSystem.css": "6f59fd9f9b7a3c29ca3521d1dd70a6a5a6a420d967bb2e29f45e881d1f6bb8a5"
};
const R39_HASHES = {
  "src/features/music/MusicPage.tsx": "d4799d1506a45b431beb50ffcf3052ea1280ad667637be2c2e6e874c414cd094",
  "src/features/music/MusicAuditionPanel.tsx": "2a0322319bbb9d99a0d20b5afc9ad653f8e40a3692cf3ae2db4c5ec12166b94f",
  "src/features/music/MusicIntelligencePanel.tsx": "c821d5369e38cc5301c4afb2b31a57a188bd2848e3ee8a950fb8089809b4940c",
  "src/features/music/premium/MusicUiPrimitives.tsx": "76c36ae377dd8a023cbfce8b58f5f65de63b3e3dfa9768bbc21c1839422191e3",
  "src/features/music/premium/MusicPremiumSelect.tsx": "4bd05e5c96cfeefbae0c65a7dc777d45480d4f10f8cbce8cc76760c9d19a97d0",
  "src/features/music/premium/MusicUiSystem.css": "e9cd758a4944036618367722a4f31ff32245b0e4c5db77950dfb50d0239e5fcd"
};
const R39_NEW_FILES = {
  "src/lib/musicTodayContext.ts": [
    "11628d286cca3d231dc049a5363a31dd0de2634a22c964f6857a300f9282f7df",
    "f6ddc21c2d072ae3b44d11a7a8adc28bf84f561ea1f3e13d8aec409822a39c47"
  ],
  "src/features/music/premium/MusicTodayAi.tsx": ["ca1316dd7cc6b76884dc9d20f6be64ae309282928b7e1df922ad6d5c74375b94"],
  "src/features/music/premium/MusicTodayAi.css": ["5c6ef60b433cbfaee96a74cf86e7b1364fa78996fa879d468e8cc50be8efaa6e"]
};
const PAYLOAD = {"src/features/music/MusicPage.tsx": "", "src/features/music/MusicAuditionPanel.tsx": "", "src/features/music/MusicIntelligencePanel.tsx": "", "src/features/music/premium/MusicUiPrimitives.tsx": "", "src/features/music/premium/MusicPremiumSelect.tsx": "", "src/features/music/premium/MusicUiSystem.css": ""};

function sha256Buffer(data) { return crypto.createHash("sha256").update(data).digest("hex"); }
function sha256File(file) { return sha256Buffer(fs.readFileSync(file)); }
function stamp() { return new Date().toISOString().replace(/[:.]/g, "-"); }

function findRepoRoot() {
  const starts = [process.cwd(), path.dirname(process.argv[1] || process.cwd()), path.resolve(process.cwd(), ".."), path.resolve(process.cwd(), "../..")];
  for (const start of starts) {
    let dir = path.resolve(start);
    for (let i = 0; i < 8; i += 1) {
      if (fs.existsSync(path.join(dir, "package.json")) && fs.existsSync(path.join(dir, "src", "features", "music"))) return dir;
      const parent = path.dirname(dir);
      if (parent === dir) break;
      dir = parent;
    }
  }
  throw new Error("Could not find the MVPTrainerPro repo root. Run this from the repo root or its /scripts folder.");
}

function stripR39PlayerInjection(source) {
  const hasImport = source.includes(PLAYER_IMPORT);
  const hasMarker = source.includes(PLAYER_RENDER_MARKER);
  const hasRender = source.includes("<MusicTodayAi />");
  if (!hasImport && !hasMarker && !hasRender) return { source, changed: false };
  if (!(hasImport && hasMarker && hasRender)) {
    throw new Error("Safety stop: MusicMiniPlayer contains only part of the R39 Today AI injection. No files were changed.");
  }
  let out = source;
  out = out.replace(new RegExp('^' + PLAYER_IMPORT.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\r?\\n(?:\\r?\\n)?', 'm'), '');
  const renderRe = /\r?\n([ \t]*)\{\/\* MVP_MUSIC_TODAY_AI_R39 \*\/\}\r?\n\1<MusicTodayAi \/>/;
  out = out.replace(renderRe, '');
  if (out.includes(PLAYER_IMPORT) || out.includes(PLAYER_RENDER_MARKER) || out.includes("<MusicTodayAi />")) {
    throw new Error("Safety stop: could not cleanly remove the R39 Today AI player injection.");
  }
  return { source: out, changed: out !== source };
}

const root = findRepoRoot();
console.log(`[${VERSION}] Repo: ${root}`);
console.log(`[${VERSION}] Restoring exact r37 My Music files and removing only the R39 Today AI additions.`);

const decoded = new Map();
for (const [rel, encoded] of Object.entries(PAYLOAD)) {
  const data = Buffer.from(encoded, "base64");
  if (sha256Buffer(data) !== R37_HASHES[rel]) throw new Error(`Embedded r37 checksum failed: ${rel}`);
  decoded.set(rel, data);
}

const plan = [];
try {
  for (const rel of Object.keys(R37_HASHES)) {
    const target = path.join(root, rel);
    if (!fs.existsSync(target)) throw new Error(`Safety stop: required My Music file is missing: ${rel}`);
    const hash = sha256File(target);
    if (hash === R37_HASHES[rel]) {
      plan.push({ rel, target, state: "already-r37", existed: true });
    } else if (hash === R39_HASHES[rel]) {
      plan.push({ rel, target, state: "restore-r37", existed: true });
    } else {
      throw new Error(`Safety stop: ${rel} is neither exact R39 nor exact r37. Current SHA256: ${hash}. This rollback will not overwrite unknown edits.`);
    }
  }

  for (const [rel, expectedHashes] of Object.entries(R39_NEW_FILES)) {
    const target = path.join(root, rel);
    if (!fs.existsSync(target)) {
      plan.push({ rel, target, state: "already-removed", existed: false });
      continue;
    }
    const hash = sha256File(target);
    if (!expectedHashes.includes(hash)) throw new Error(`Safety stop: R39-created file ${rel} was modified after install. Current SHA256: ${hash}. It will not be deleted.`);
    plan.push({ rel, target, state: "remove-r39-new", existed: true });
  }

  const playerPath = path.join(root, PLAYER_FILE);
  if (!fs.existsSync(playerPath)) throw new Error(`Safety stop: missing current player: ${PLAYER_FILE}`);
  const playerOriginal = fs.readFileSync(playerPath, "utf8");
  const stripped = stripR39PlayerInjection(playerOriginal);
  plan.push({ rel: PLAYER_FILE, target: playerPath, state: stripped.changed ? "strip-player-r39" : "player-clean", existed: true, originalText: playerOriginal, text: stripped.source });
} catch (error) {
  console.error(`[${VERSION}] ${String(error?.message || error)}`);
  console.error(`[${VERSION}] No files were changed.`);
  process.exit(2);
}

const pending = plan.filter((x) => ["restore-r37", "remove-r39-new", "strip-player-r39"].includes(x.state));
if (!pending.length) {
  console.log(`[${VERSION}] Already rolled back. No files changed.`);
  process.exit(0);
}

const backupRoot = path.join(root, ".mvp-backups", `${VERSION}-${stamp()}`);
fs.mkdirSync(backupRoot, { recursive: true });
const written = [];

try {
  for (const item of pending) {
    if (item.existed && fs.existsSync(item.target)) {
      const backup = path.join(backupRoot, item.rel);
      fs.mkdirSync(path.dirname(backup), { recursive: true });
      fs.copyFileSync(item.target, backup);
    }
  }

  for (const item of pending) {
    if (item.state === "restore-r37") {
      if (sha256File(item.target) !== R39_HASHES[item.rel]) throw new Error(`Concurrent-change safety stop: ${item.rel} changed after validation.`);
      fs.writeFileSync(item.target, decoded.get(item.rel));
    } else if (item.state === "remove-r39-new") {
      if (!R39_NEW_FILES[item.rel].includes(sha256File(item.target))) throw new Error(`Concurrent-change safety stop: ${item.rel} changed after validation.`);
      fs.rmSync(item.target);
    } else if (item.state === "strip-player-r39") {
      if (fs.readFileSync(item.target, "utf8") !== item.originalText) throw new Error(`Concurrent-change safety stop: ${PLAYER_FILE} changed after validation.`);
      fs.writeFileSync(item.target, item.text, "utf8");
    }
    written.push(item);
    console.log(` - ${item.rel}`);
  }

  for (const rel of Object.keys(R37_HASHES)) {
    const target = path.join(root, rel);
    if (!fs.existsSync(target) || sha256File(target) !== R37_HASHES[rel]) throw new Error(`Post-rollback r37 checksum failed: ${rel}`);
  }
  for (const rel of Object.keys(R39_NEW_FILES)) {
    if (fs.existsSync(path.join(root, rel))) throw new Error(`Post-rollback cleanup failed: ${rel} still exists.`);
  }
  const player = fs.readFileSync(path.join(root, PLAYER_FILE), "utf8");
  if (player.includes(PLAYER_IMPORT) || player.includes(PLAYER_RENDER_MARKER) || player.includes("<MusicTodayAi />")) throw new Error("Post-rollback player cleanup failed.");
} catch (error) {
  console.error(`[${VERSION}] ROLLBACK ERROR: ${String(error?.message || error)}`);
  console.error(`[${VERSION}] Restoring the state from immediately before this rollback attempt...`);
  for (const item of written.reverse()) {
    try {
      const backup = path.join(backupRoot, item.rel);
      if (fs.existsSync(backup)) {
        fs.mkdirSync(path.dirname(item.target), { recursive: true });
        fs.copyFileSync(backup, item.target);
      } else if (item.state === "remove-r39-new") {
        // This state always has a backup because the file existed before deletion.
        throw new Error(`Missing rollback safety backup for ${item.rel}`);
      }
    } catch (restoreError) {
      console.error(` ! Could not restore ${item.rel}: ${String(restoreError?.message || restoreError)}`);
    }
  }
  process.exit(2);
}

console.log(`[${VERSION}] COMPLETE.`);
console.log(`[${VERSION}] Exact r37 My Music UI restored.`);
console.log(`[${VERSION}] R39 Today AI files removed and its MusicMiniPlayer injection stripped.`);
console.log(`[${VERSION}] Current DSP/WASM, AudioWorklet, R2/Supabase routing, MusicLibraryVisualEngine, and all unrelated files were untouched.`);
console.log(`[${VERSION}] Safety backup of the pre-rollback R39 state: ${backupRoot}`);
console.log("Next: npm run build");
